// Illustrates how to recover the iterator functionality that existed
// in Commons Math (v3.6.1) but was not ported to "Commons Numbers".
@Test
void testCommonsMathIterator() {
    final int[] sizes = new int[] { 3, 2, 5 };
    final org.apache.commons.math3.util.MultidimensionalCounter.Iterator cmIter = new org.apache.commons.math3.util.MultidimensionalCounter(sizes).iterator();
    final MultidimensionalCounter counter = MultidimensionalCounter.of(sizes);
    Assertions.assertTrue(cmIter.hasNext());
    Assertions.assertTrue(counter.getSize() > 0);
    for (int i = 0; i < counter.getSize(); i++) {
        cmIter.next();
        Assertions.assertArrayEquals(cmIter.getCounts(), counter.toMulti(i));
    }
    Assertions.assertFalse(cmIter.hasNext());
}

@ParameterizedTest
@MethodSource(value = { "testDoubleHeapSelect", "testDoubleSelectMinMax", "testDoubleSelectMinMax2" })
void testDoubleHeapSelectLeft(double[] values, int from, int to) {
    final double[] sorted = sort(values, from, to);
    final double[] x = values.clone();
    final DoubleRangePartitionFunction fun = QuickSelect::heapSelectLeft;
    for (int k = from; k <= to; k++) {
        assertPartitionRange(sorted, fun, x.clone(), from, to, k, k);
        if (k > from) {
            // Sort an extra 1
            assertPartitionRange(sorted, fun, x.clone(), from, to, k - 1, k);
            if (k > from + 1) {
                // Sort all
                // Test clipping with k < from
                assertPartitionRange(sorted, fun, x.clone(), from, to, from - 23, k);
            }
        }
    }
}

