    // Because they are adjacent floating point numbers, "a" and "b" are
    // considered equal even though the allowed error is smaller than
    // their difference.
    Assertions.assertTrue(fun.equals(a, b, 0.5f * diff));
    final float c = Math.nextUp(b);
