@Test
void testSumOfProducts() {
    // arrange
    final BigDecimal[] aFN = new BigDecimal[] { BigDecimal.valueOf(-1321008684645961L), BigDecimal.valueOf(-5774608829631843L), BigDecimal.valueOf(-7645843051051357L) };
    final BigDecimal[] aFD = new BigDecimal[] { BigDecimal.valueOf(268435456L), BigDecimal.valueOf(268435456L), BigDecimal.valueOf(8589934592L) };
    final BigDecimal[] bFN = new BigDecimal[] { BigDecimal.valueOf(-5712344449280879L), BigDecimal.valueOf(-4550117129121957L), BigDecimal.valueOf(8846951984510141L) };
    final BigDecimal[] bFD = new BigDecimal[] { BigDecimal.valueOf(2097152L), BigDecimal.valueOf(2097152L), BigDecimal.valueOf(131072L) };
    final int len = aFN.length;
    final double[] a = new double[len];
    final double[] b = new double[len];
    for (int i = 0; i < len; i++) {
        a[i] = aFN[i].doubleValue() / aFD[i].doubleValue();
        b[i] = bFN[i].doubleValue() / bFD[i].doubleValue();
    }
    // act
    final double sum = Sum.ofProducts(a, b).getAsDouble();
    // assert
    // Compare with arbitrary precision computation.
    BigDecimal result = BigDecimal.ZERO;
    for (int i = 0; i < a.length; i++) {
        result = result.add(aFN[i].divide(aFD[i]).multiply(bFN[i].divide(bFD[i])));
    }
    final double expected = result.doubleValue();
    Assertions.assertEquals(expected, sum, 1e-15);
    final double naive = a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
    Assertions.assertTrue(Math.abs(naive - sum) > 1.5);
}

