    assertEquals(1, f.getNumerator());
    assertEquals(1, f.getDenominator());
    f1 = Fraction.of(Integer.MIN_VALUE, Integer.MAX_VALUE);
    f2 = Fraction.of(1, Integer.MAX_VALUE);
