@Test
void testBeta1() {
    final double tol = 1e-14;
    final double[] xs = { 0.0, Double.MIN_NORMAL, 1e-132, 0.1, 0.5, 0.99, 0.99999, Math.nextDown(1.0), 1 };
    final double[] as = { 0.1, 0.5, 1, 2, 10 };
    for (final double x : xs) {
        for (final double a : as) {
            final double expected = Math.pow(x, a);
            Assertions.assertEquals(expected, RegularizedBeta.value(x, a, 1), expected * tol, () -> String.format("x=%s, a=%s", x, a));
        }
    }
}

@Test
void testAlpha1() {
    final double tol = 1e-14;
    final double[] xs = { 0.0, Double.MIN_NORMAL, 1e-132, 0.1, 0.5, 0.99, 0.99999, Math.nextDown(1.0), 1 };
    final double[] bs = { 0.1, 0.5, 1, 2, 10 };
    for (final double x : xs) {
        for (final double b : bs) {
            // 1 - (1-x)^b
            // When x > 0.5 then 1-x is exact and we use the power function.
            // Otherwise use log functions:
            // 1 - exp(b * log(1-x))
            final double expected = x >= 0.5 ? 1.0 - Math.pow(1 - x, b) : -Math.expm1(b * Math.log1p(-x));
            Assertions.assertEquals(expected, RegularizedBeta.value(x, 1, b), expected * tol, () -> String.format("x=%s, b=%s", x, b));
        }
    }
}

